d(r) as (select jsonb_array_elements($json$[{"k":"bal-a-breakfast","f":"balanced","d":"A","m":"breakfast","n":"Berry overnight oats","ds":"Creamy oats soaked overnight with Greek yoghurt, milk and berries. Make it before bed and breakfast is done.","pr":5,"ck":0,"st":["Grab a jar or container with a lid that holds about 500 ml.","Add the rolled oats and chia seeds to the jar.","Pour in the milk and stir well so all the oats are wet. Scrape the bottom so no dry oats are hiding there.","Spoon in the Greek yoghurt and the honey and stir again until smooth.","Tip the frozen berries on top. No need to thaw them, they defrost overnight and the juice runs into the oats.","Put the lid on and leave it in the fridge for at least 4 hours, or overnight.","In the morning give it a stir. If it is too thick, add a splash of milk. Eat it cold straight from the jar."],"tp":"Make three jars on Sunday night for Monday, Wednesday and Friday. They keep for 3 days in the fridge.","dt":[],"c":501,"p":23.6,"cb":64.8,"ft":13.1,"ps":0,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Reduced fat milk",1,180,"3/4 cup",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Chia seeds",4,10,"2 tsp",null,null],["Honey",5,10,"1/2 tbsp",null,null]]},{"k":"bal-a-lunch","f":"balanced","d":"A","m":"lunch","n":"Teriyaki chicken rice bowl","ds":"Sticky soy and honey chicken with rice, broccoli and carrot. Great hot or cold from a lunchbox.","pr":10,"ck":15,"st":["Rinse the rice in a sieve under cold water until the water runs mostly clear. Put it in a small saucepan with 140 ml (just over 1/2 cup) of water.","Bring the rice to the boil, then turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Turn the heat off and leave the lid on for 5 more minutes.","While the rice cooks, cut the chicken into bite-sized pieces about 2 cm wide. Peel and finely chop the garlic. Peel the carrot and cut it into thin sticks. Cut the broccoli into small florets.","In a cup, mix the soy sauce, honey and chopped garlic. This is your teriyaki sauce.","Heat the sesame oil in a frying pan over medium-high heat. Add the chicken and cook for 5 to 6 minutes, turning the pieces, until golden on the outside and white all the way through.","Add the carrot and broccoli with 2 tablespoons of water. Cook for 3 minutes, stirring, until the broccoli is bright green and just tender.","Pour in the teriyaki sauce and stir for 1 minute until it bubbles and coats everything.","Spoon the rice into a bowl, add the chicken and vegetables on top and sprinkle with sesame seeds."],"tp":"Cut into the thickest piece of chicken to check it is cooked: no pink inside.","dt":[],"c":543,"p":45.1,"cb":65.4,"ft":9,"ps":1,"i":[["Chicken breast",6,150,"1 small breast",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Broccoli",8,100,"1 cup of small florets",null,null],["Carrot",9,60,"1/2 medium carrot",null,null],["Salt-reduced soy sauce",10,15,"1 tbsp",null,null],["Honey",5,10,"1/2 tbsp",null,null],["Garlic",11,5,"1 clove",null,null],["Sesame oil",12,5,"1 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"bal-a-dinner","f":"balanced","d":"A","m":"dinner","n":"Lean beef spaghetti bolognese","ds":"The family classic, made with lean mince and extra vegetables hidden in the sauce.","pr":10,"ck":25,"st":["Fill a large saucepan with water, add a pinch of salt and put it on to boil for the pasta.","Peel and finely chop the onion and garlic. Grate the carrot and zucchini on the large holes of a grater.","Heat the olive oil in a frying pan over medium heat. Add the onion and cook for 3 minutes until soft.","Add the mince and turn the heat up to medium-high. Break it up with a wooden spoon and cook for 5 minutes until browned all over with no pink left.","Stir in the garlic, carrot and zucchini and cook for 2 minutes.","Pour in the canned tomatoes, add the oregano and 50 ml of water. Season with a pinch of salt and pepper. Bring to a simmer, then turn the heat down to low and cook for 10 to 15 minutes, stirring now and then, until thick.","While the sauce simmers, add the spaghetti to the boiling water and cook for the time on the packet (usually 9 to 11 minutes). Drain.","Put the spaghetti in a bowl, spoon the sauce over and finish with the grated parmesan."],"tp":"The sauce freezes well for up to 3 months. Cook a big batch and freeze it in single serves.","dt":[],"c":654,"p":52.1,"cb":70,"ft":15.4,"ps":2,"i":[["Lean beef mince (5% fat)",14,150,"150 g",null,null],["Spaghetti, dry",15,80,"80 g (a bundle the width of a 20c coin)",null,null],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Zucchini",18,70,"1/2 medium zucchini",null,null],["Garlic",11,6,"1 to 2 cloves",null,null],["Olive oil",19,5,"1 tsp",null,null],["Parmesan, grated",20,10,"1 tbsp",null,null],["Dried oregano or Italian herbs",21,1,"1/2 tsp",null,null]]},{"k":"bal-a-snack","f":"balanced","d":"A","m":"snack","n":"Peanut butter and banana toast","ds":"A quick, filling snack before or after training.","pr":3,"ck":2,"st":["Toast the slice of bread until golden.","Spread the peanut butter over the toast while it is still warm so it melts slightly.","Peel the banana and slice half of it into thin rounds.","Lay the banana slices over the peanut butter and sprinkle with a pinch of cinnamon."],"tp":"Wrap the other half of the banana tightly in cling wrap and keep it for tomorrow.","dt":[],"c":247,"p":8.6,"cb":29.1,"ft":9.2,"ps":3,"i":[["Wholemeal bread",22,40,"1 slice",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Banana",24,60,"1/2 medium banana",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"bal-b-breakfast","f":"balanced","d":"B","m":"breakfast","n":"Scrambled eggs on toast with spinach and tomatoes","ds":"Soft, creamy scrambled eggs on wholemeal toast with wilted spinach and cherry tomatoes.","pr":5,"ck":8,"st":["Crack the eggs into a bowl, add the milk and a pinch of salt and pepper, and whisk with a fork until no streaks of white are left.","Cut the cherry tomatoes in half. Put the bread in the toaster.","Melt the butter in a non-stick frying pan over medium-low heat. Add the tomatoes and cook for 2 minutes until they start to soften.","Add the spinach and stir for 30 seconds until it wilts. Push the vegetables to one side of the pan.","Pour the eggs into the empty side. Wait 20 seconds, then gently push the eggs from the edge to the middle with a spatula. Keep doing this slowly.","Take the pan off the heat when the eggs are still slightly wet and shiny. They keep cooking for a few seconds off the heat.","Put the toast on a plate, spoon the eggs over and serve the spinach and tomatoes on the side."],"tp":"Low heat is the secret to soft eggs. High heat makes them rubbery.","dt":[],"c":427,"p":28.8,"cb":31.7,"ft":18.9,"ps":4,"i":[["Eggs",26,150,"3 eggs","egg",50],["Wholemeal bread",22,70,"2 slices",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Reduced fat milk",1,20,"1 tbsp",null,null],["Butter",29,5,"1 tsp",null,null]]},{"k":"bal-b-lunch","f":"balanced","d":"B","m":"lunch","n":"Chicken, avocado and salad wrap","ds":"A fresh, crunchy wrap with grilled chicken, avocado, cheese and salad.","pr":10,"ck":10,"st":["Put the chicken breast between two sheets of baking paper and flatten it with a rolling pin or the bottom of a pan until it is an even 1.5 cm thick. This helps it cook evenly.","Rub the chicken with the olive oil and a pinch of salt, pepper and any dried herbs you like.","Heat a frying pan or grill pan over medium-high heat. Cook the chicken for 4 to 5 minutes on each side until golden and cooked through with no pink in the middle. Rest it on a board for 3 minutes, then slice.","While the chicken cooks, slice the tomato and cucumber thinly and shred the lettuce.","Mash the avocado in a small bowl with the lemon juice and a pinch of salt.","Lay the wrap flat. Spread the avocado down the middle, then add lettuce, tomato, cucumber, chicken and cheese.","Add the yoghurt on top as a dressing.","Fold the bottom of the wrap up over the filling, then fold the sides in and roll it up tightly. Cut in half to serve."],"tp":"Taking it to work? Wrap it tightly in baking paper and keep it cold until lunch.","dt":[],"c":497,"p":39.4,"cb":35.6,"ft":20.4,"ps":5,"i":[["Chicken breast",6,120,"1 small breast",null,null],["Wholemeal wrap",30,60,"1 large wrap",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Cos lettuce",32,30,"2 leaves",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Cucumber",34,40,"1/4 cucumber",null,null],["Cheddar, grated",35,15,"2 tbsp",null,null],["Greek yoghurt, low fat",2,30,"1 tbsp",null,null],["Olive oil",19,3,"a drizzle",null,null],["Lemon juice",36,5,"1 tsp",null,null]]},{"k":"bal-b-dinner","f":"balanced","d":"B","m":"dinner","n":"Beef burrito bowl","ds":"Mexican spiced mince with brown rice, black beans, corn, salad and a cool yoghurt topping.","pr":10,"ck":25,"st":["Rinse the brown rice and put it in a saucepan with 150 ml of water. Bring to the boil, turn the heat to low, put the lid on and cook for 25 minutes until the water is gone. Leave it covered off the heat for 5 minutes.","Meanwhile, heat the oil in a frying pan over medium-high heat. Add the mince and break it up with a wooden spoon. Cook for 5 minutes until browned with no pink left.","Sprinkle in the spice mix and 3 tablespoons of water. Stir and cook for 2 minutes until the mince is coated and saucy.","Tip the black beans and corn into a sieve, rinse under the tap and drain. Warm them in the pan with the mince for 2 minutes.","Dice the capsicum and tomato into small cubes. Shred the lettuce.","Put the rice in a bowl. Arrange the mince, beans and corn, capsicum, tomato and lettuce on top in sections.","Finish with the cheese and a spoonful of yoghurt, and squeeze the lime over everything."],"tp":"Use microwave brown rice pouches on busy nights. Use 120 g of cooked rice per serve.","dt":[],"c":697,"p":50.8,"cb":75.8,"ft":17.5,"ps":6,"i":[["Lean beef mince (5% fat)",14,130,"130 g",null,null],["Brown rice, uncooked",37,60,"1/4 cup plus 1 tbsp",null,null],["Canned black beans, drained",38,70,"1/3 cup",null,null],["Canned corn kernels, drained",39,50,"1/4 cup",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Cos lettuce",32,30,"2 leaves",null,null],["Cheddar, grated",35,15,"2 tbsp",null,null],["Greek yoghurt, low fat",2,40,"2 tbsp",null,null],["Taco or Mexican spice mix",41,6,"2 tsp",null,null],["Olive oil",19,3,"a drizzle",null,null],["Lime",42,10,"1 wedge",null,null]]},{"k":"bal-b-snack","f":"balanced","d":"B","m":"snack","n":"Greek yoghurt with honey and walnuts","ds":"Thick yoghurt, a drizzle of honey and crunchy walnuts. High protein and ready in a minute.","pr":2,"ck":0,"st":["Spoon the yoghurt into a bowl.","Roughly break the walnuts into smaller pieces with your fingers and scatter them over the yoghurt.","Drizzle the honey over the top and eat straight away so the walnuts stay crunchy."],"tp":"Pack the walnuts in a separate container if you are taking it to work.","dt":[],"c":285,"p":15,"cb":21.8,"ft":14,"ps":7,"i":[["Greek yoghurt, low fat",2,170,"2/3 cup",null,null],["Walnuts",43,15,"5 walnut halves",null,null],["Honey",5,10,"1/2 tbsp",null,null]]},{"k":"bal-c-breakfast","f":"balanced","d":"C","m":"breakfast","n":"Banana pancakes with yoghurt","ds":"Fluffy Sunday pancakes with banana in the batter, served with Greek yoghurt and maple syrup.","pr":10,"ck":10,"st":["Mash half the banana in a mixing bowl with a fork until smooth. Slice the rest for the top.","Add the egg and milk to the mashed banana and whisk together.","Add the flour and stir with a spoon until just combined. A few small lumps are fine. Do not over-mix or the pancakes go tough.","Heat a non-stick frying pan over medium heat and add a little of the butter. When it sizzles, pour in about 3 tablespoons of batter per pancake. You should get 4 to 5 small pancakes.","Cook until bubbles pop on the top and the edges look dry, about 2 minutes. Flip and cook the other side for 1 minute until golden. Add a little more butter between batches.","Stack the pancakes on a plate. Top with the yoghurt, the sliced banana and a drizzle of maple syrup."],"tp":"If the first pancake is too dark, turn the heat down a little. The first one is always the test.","dt":[],"c":540,"p":24.2,"cb":79.8,"ft":11.9,"ps":8,"i":[["Self-raising flour",44,60,"1/2 cup",null,null],["Egg",26,50,"1 egg","egg",50],["Reduced fat milk",1,100,"1/3 cup plus 1 tbsp",null,null],["Banana",24,80,"2/3 banana",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Maple syrup",45,10,"2 tsp",null,null],["Butter",29,4,"1 tsp",null,null]]},{"k":"bal-c-lunch","f":"balanced","d":"C","m":"lunch","n":"Ham, cheese and tomato toastie with side salad","ds":"A golden toasted sandwich with a crisp side salad. Proper Sunday lunch comfort.","pr":5,"ck":6,"st":["Slice the tomato into thin rounds.","Lay one slice of bread flat. Top with the cheese, ham and tomato, then the second slice of bread.","Heat a frying pan over medium heat, or use a sandwich press. Cook the sandwich for 2 to 3 minutes each side, pressing down with a spatula, until golden and the cheese has melted. No butter needed in a non-stick pan.","While it cooks, slice the cucumber and put it in a bowl with the salad leaves.","Whisk the olive oil, balsamic and a pinch of salt and pepper in a cup and toss it through the salad.","Cut the toastie in half and serve with the salad."],"tp":"Let it sit for a minute before cutting so the cheese does not run out.","dt":[],"c":426,"p":26,"cb":36.7,"ft":16.8,"ps":9,"i":[["Wholemeal bread",22,80,"2 slices",null,null],["Lean leg ham",46,60,"3 slices",null,null],["Cheddar, sliced",35,25,"1 thick slice",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Mixed salad leaves",47,40,"1 large handful",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Olive oil",19,5,"1 tsp",null,null],["Balsamic vinegar",48,5,"1 tsp",null,null]]},{"k":"bal-c-dinner","f":"balanced","d":"C","m":"dinner","n":"Sunday roast chicken thighs with vegetables","ds":"Crispy herb chicken thighs roasted on one tray with potato, pumpkin and green beans.","pr":15,"ck":40,"st":["Heat the oven to 200°C (180°C fan). Line a large tray with baking paper.","Peel the potato and cut it into 3 cm chunks. Peel the pumpkin and cut it into chunks the same size. Smaller pieces cook faster.","Put the potato and pumpkin on the tray, drizzle with half the oil, sprinkle with half the rosemary, salt and pepper, and toss with your hands. Roast for 15 minutes.","Meanwhile, rub the chicken thighs with the remaining oil, rosemary, crushed garlic, lemon juice, salt and pepper.","Take the tray out, turn the vegetables over and push them to the sides. Put the chicken in the middle. Roast for another 20 to 25 minutes.","In the last 8 minutes, add the green beans to the tray.","The chicken is ready when the juices run clear when you cut into the thickest part. The vegetables should be golden and soft when pierced with a knife.","Rest the chicken for 3 minutes, then serve with the vegetables and any juices from the tray poured over."],"tp":"Roast extra chicken and vegetables. They make an easy lunch the next day.","dt":[],"c":454,"p":41.2,"cb":34.5,"ft":14.4,"ps":10,"i":[["Chicken thigh fillets, skinless",49,170,"2 small fillets",null,null],["Potato",50,180,"1 medium potato",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Green beans",52,80,"1 handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh or dried rosemary",53,1,"1 tsp",null,null],["Lemon",36,10,"1/2 tbsp",null,null]]},{"k":"bal-c-snack","f":"balanced","d":"C","m":"snack","n":"Banana peanut butter smoothie","ds":"A thick, creamy smoothie that tastes like a milkshake.","pr":5,"ck":0,"st":["Peel the banana and break it into chunks. For an extra thick smoothie, use a banana you froze earlier.","Put the milk, banana, peanut butter, cocoa and ice into a blender.","Blend on high for 30 to 45 seconds until completely smooth and frothy.","Pour into a tall glass and drink straight away."],"tp":"Freeze peeled, overripe bananas in chunks so you always have one ready for smoothies.","dt":[],"c":263,"p":12.9,"cb":29.3,"ft":9.4,"ps":11,"i":[["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,10,"2 tsp",null,null],["Cocoa powder",54,5,"1 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]},{"k":"bud-a-breakfast","f":"budget","d":"A","m":"breakfast","n":"Peanut butter banana porridge","ds":"Hot, creamy porridge in 5 minutes, topped with banana and peanut butter.","pr":2,"ck":5,"st":["Put the oats and milk in a small saucepan, or a large microwave-safe bowl.","Stovetop: cook over medium heat for 4 to 5 minutes, stirring often, until thick and creamy. Microwave: cook on high for 2 minutes, stir, then cook for 1 more minute. Watch it so it does not boil over.","Let it stand for 1 minute to thicken. Add a splash more milk if you like it runnier.","Slice the banana over the top, add the peanut butter and sprinkle with cinnamon."],"tp":"Buy oats and peanut butter in large tubs from the supermarket home brand. It is the cheapest breakfast going.","dt":[],"c":503,"p":20.3,"cb":62.1,"ft":17,"ps":12,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"bud-a-lunch","f":"budget","d":"A","m":"lunch","n":"Tuna, rice and veggie bowl","ds":"Pantry staples turned into a proper meal: tuna, rice, corn and frozen veg with sweet chilli.","pr":5,"ck":12,"st":["Rinse the rice and put it in a small saucepan with 140 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave it covered for 5 minutes off the heat.","While the rice cooks, put the frozen vegetables in a microwave-safe bowl with 1 tablespoon of water. Cover and microwave on high for 3 minutes, then drain.","Drain the tuna well and flake it with a fork.","Slice the spring onion thinly.","Put the rice in a bowl, add the vegetables and tuna, drizzle with the soy sauce and sweet chilli sauce, and top with spring onion."],"tp":"Cook a big pot of rice at the start of the week. Cooked rice keeps for 3 days in the fridge. Reheat until steaming hot.","dt":[],"c":443,"p":32.3,"cb":67.5,"ft":3.2,"ps":13,"i":[["Tuna in springwater, drained",56,95,"1 small can",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Frozen mixed vegetables",57,120,"1 cup",null,null],["Sweet chilli sauce",58,15,"1 tbsp",null,null],["Salt-reduced soy sauce",10,10,"2 tsp",null,null],["Spring onion",59,10,"1 stem",null,null]]},{"k":"bud-a-dinner","f":"budget","d":"A","m":"dinner","n":"Beef and bean chilli with rice","ds":"A big-batch chilli that stretches lean mince with kidney beans. Cheap, filling and freezes well.","pr":10,"ck":25,"st":["Start the rice: rinse it and put it in a saucepan with 120 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave it covered off the heat.","Peel and dice the onion. Heat the oil in a frying pan over medium heat and cook the onion for 3 minutes until soft.","Add the mince, turn the heat up and break it up with a spoon. Cook for 5 minutes until browned.","Stir in the chilli powder and cumin and cook for 30 seconds until it smells toasty.","Add the tomatoes, the drained kidney beans and 50 ml of water. Season with salt and pepper. Simmer on low for 12 to 15 minutes until thick.","Serve the chilli over the rice with a spoonful of yoghurt on top."],"tp":"Not a fan of heat? Leave out the chilli powder and use smoked paprika instead.","dt":[],"c":569,"p":42.3,"cb":68.4,"ft":10.4,"ps":14,"i":[["Lean beef mince (5% fat)",14,120,"120 g",null,null],["Canned red kidney beans, drained",60,100,"1/2 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["White rice, uncooked",7,60,"1/4 cup plus 1 tbsp",null,null],["Natural yoghurt",61,30,"1 heaped tbsp",null,null],["Chilli powder",62,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,3,"a drizzle",null,null]]},{"k":"bud-a-snack","f":"budget","d":"A","m":"snack","n":"Cheese, crackers and an apple","ds":"The no-cook lunchbox snack: crackers, cheddar and a crunchy apple.","pr":3,"ck":0,"st":["Slice the cheese into thin pieces that fit on the crackers.","Wash the apple and cut it into wedges, removing the core.","Top each cracker with cheese and eat with the apple on the side."],"tp":"Squeeze a little lemon juice over the apple wedges to stop them going brown in a lunchbox.","dt":[],"c":252,"p":10.1,"cb":32.4,"ft":7.9,"ps":15,"i":[["Wholegrain crackers",64,25,"4 crackers",null,null],["Cheddar, reduced fat",65,25,"2 slices",null,null],["Apple",66,130,"1 medium apple",null,null]]},{"k":"bud-b-breakfast","f":"budget","d":"B","m":"breakfast","n":"Baked beans and eggs on toast","ds":"The cheapest high-protein breakfast there is. Warm beans, eggs and toast in 8 minutes.","pr":2,"ck":8,"st":["Put the baked beans in a small saucepan over low heat, or in a microwave-safe bowl covered with a plate (microwave for 90 seconds, stir halfway).","Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat it over medium heat. Crack in the eggs and cook for 3 minutes for a runny yolk, or 4 to 5 minutes for a firm yolk. Put a lid on the pan to cook the tops.","Put the toast on a plate, spoon the hot beans over and top with the eggs. Season with pepper."],"tp":"Pick the salt-reduced baked beans. They taste the same and have about a third less salt.","dt":[],"c":448,"p":27.1,"cb":47.2,"ft":12.8,"ps":16,"i":[["Baked beans in tomato sauce",67,150,"1/2 can",null,null],["Eggs",26,100,"2 eggs","egg",50],["Wholemeal bread",22,70,"2 slices",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"bud-b-lunch","f":"budget","d":"B","m":"lunch","n":"Chicken, pea and corn pasta salad","ds":"A creamy pasta salad you can make the night before and eat cold.","pr":10,"ck":12,"st":["Boil a saucepan of salted water and cook the pasta for the time on the packet. In the last 2 minutes, add the frozen peas to the same pot.","Drain the pasta and peas and rinse under cold water until cool. Shake off as much water as you can.","Shred the cooked chicken with two forks. A supermarket roast chicken or leftover chicken is perfect, just take off the skin.","In a large bowl, stir together the mayonnaise, yoghurt, a pinch of salt and plenty of pepper.","Add the pasta, peas, drained corn, chicken and sliced spring onion and stir until everything is coated.","Eat straight away or keep in the fridge for up to 2 days."],"tp":"A whole supermarket roast chicken gives about 4 serves of this salad for a few dollars each.","dt":[],"c":527,"p":44.6,"cb":64.2,"ft":8.3,"ps":17,"i":[["Pasta shapes, dry",15,70,"3/4 cup",null,null],["Cooked chicken breast",68,100,"1 cup shredded",null,null],["Frozen peas",69,50,"1/3 cup",null,null],["Canned corn kernels, drained",39,40,"1/4 cup",null,null],["Light mayonnaise",70,15,"1 tbsp",null,null],["Natural yoghurt",61,30,"1 heaped tbsp",null,null],["Spring onion",59,10,"1 stem",null,null]]},{"k":"bud-b-dinner","f":"budget","d":"B","m":"dinner","n":"Sausage and vegetable tray bake","ds":"Lean sausages roasted on one tray with potato, capsicum and onion. Minimal washing up.","pr":10,"ck":35,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Scrub the potato (no need to peel) and cut it into 3 cm chunks. Cut the capsicum into strips and the onion into wedges.","Put the potato on the tray, drizzle with the oil, sprinkle with the herbs, salt and pepper, and toss. Roast for 10 minutes.","Add the sausages, capsicum and onion to the tray. Roast for 20 to 25 minutes, turning the sausages halfway, until browned and cooked through.","In the last 8 minutes, add the frozen green beans to the tray.","Check a sausage is cooked by cutting one in half: no pink inside. Serve everything straight from the tray."],"tp":"Prick the sausages once or twice with a fork before roasting so they do not split.","dt":[],"c":437,"p":25.9,"cb":39.4,"ft":16.8,"ps":18,"i":[["Lean beef sausages",71,140,"2 thick sausages",null,null],["Potato",72,200,"1 large potato",null,null],["Red capsicum",40,80,"1/2 capsicum",null,null],["Red onion",73,60,"1/2 onion",null,null],["Frozen green beans",74,80,"1 cup",null,null],["Olive oil",19,5,"1 tsp",null,null],["Dried mixed herbs",75,1,"1/2 tsp",null,null]]},{"k":"bud-b-snack","f":"budget","d":"B","m":"snack","n":"Yoghurt and muesli cup","ds":"Creamy yoghurt with crunchy muesli. Assemble in a cup and go.","pr":2,"ck":0,"st":["Spoon the yoghurt into a cup or small container.","Sprinkle the muesli and sultanas over the top.","Eat straight away for crunch, or leave in the fridge overnight for a softer, bircher-style snack."],"tp":"Buy a 1 kg tub of yoghurt instead of single tubs. It costs about half as much per serve.","dt":[],"c":230,"p":13.9,"cb":32.8,"ft":3.4,"ps":19,"i":[["Natural yoghurt, low fat",76,150,"2/3 cup",null,null],["Untoasted muesli",77,30,"1/3 cup",null,null],["Sultanas",78,10,"1 tbsp",null,null]]},{"k":"bud-c-breakfast","f":"budget","d":"C","m":"breakfast","n":"Cheesy omelette with toast","ds":"A fluffy three egg omelette with cheese, tomato and spinach.","pr":5,"ck":6,"st":["Crack the eggs into a bowl, add a pinch of salt and pepper and whisk until smooth.","Dice the tomato. Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat over medium heat. Pour in the eggs and tilt the pan so they cover the base.","Cook for about 1 minute until the edges start to set. Use a spatula to pull the set edges into the middle and let the runny egg flow underneath.","When the top is almost set but still slightly wet, scatter the cheese, tomato and spinach over one half.","Fold the empty half over the filling. Cook for 30 seconds more so the cheese melts, then slide onto a plate with the toast."],"tp":"Use whatever leftover vegetables are in the fridge. Mushrooms, capsicum and onion all work.","dt":[],"c":384,"p":29.9,"cb":18,"ft":20.5,"ps":20,"i":[["Eggs",26,150,"3 eggs","egg",50],["Cheddar, reduced fat, grated",65,20,"1/4 cup",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Baby spinach",27,30,"1 handful",null,null],["Wholemeal bread",22,40,"1 slice",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"bud-c-lunch","f":"budget","d":"C","m":"lunch","n":"Ham and pineapple pita pizza","ds":"Pizza in 10 minutes using a pita bread as the base.","pr":5,"ck":10,"st":["Heat the oven to 220°C (200°C fan) and line a tray with baking paper.","Put the pita on the tray and spread the tomato paste over it, leaving a 1 cm border.","Slice the mushrooms and capsicum thinly. Tear the ham into pieces.","Scatter half the cheese over the base, then the ham, pineapple, mushroom and capsicum, then the rest of the cheese.","Sprinkle with oregano and bake for 8 to 10 minutes until the cheese is bubbling and the edges are crisp.","Let it cool for 1 minute, then cut into quarters."],"tp":"Put the pita straight on the oven rack for the last 2 minutes for an extra crispy base.","dt":[],"c":377,"p":23.2,"cb":42.6,"ft":9.9,"ps":21,"i":[["Wholemeal pita bread",79,70,"1 large pita",null,null],["Tomato paste",80,20,"1 tbsp",null,null],["Lean leg ham",46,50,"2 to 3 slices",null,null],["Mozzarella, grated",81,30,"1/3 cup",null,null],["Pineapple pieces, drained",82,40,"1/4 cup",null,null],["Mushrooms",83,40,"2 mushrooms",null,null],["Red capsicum",40,40,"1/4 capsicum",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"bud-c-dinner","f":"budget","d":"C","m":"dinner","n":"Honey garlic chicken thighs with rice and veg","ds":"Sticky, sweet and savoury chicken thighs in one pan with rice and frozen vegetables.","pr":5,"ck":20,"st":["Rinse the rice and put it in a saucepan with 140 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave covered off the heat.","Crush or finely chop the garlic. In a cup, mix the honey, soy sauce, garlic and 2 tablespoons of water.","Heat the oil in a frying pan over medium-high heat. Add the chicken thighs and cook for 5 minutes each side until golden.","Turn the heat down to medium and pour in the honey garlic sauce. Let it bubble for 2 to 3 minutes, turning the chicken, until the sauce is sticky and the chicken is cooked through.","Microwave the frozen vegetables in a covered bowl with 1 tablespoon of water for 3 minutes. Drain.","Serve the chicken on the rice with the vegetables, and spoon the sauce from the pan over the top."],"tp":"Thigh fillets are cheaper than breast and stay juicy, so they are hard to overcook.","dt":[],"c":518,"p":36.6,"cb":68,"ft":9.4,"ps":22,"i":[["Chicken thigh fillets, skinless",49,150,"2 small fillets",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Frozen mixed vegetables",57,120,"1 cup",null,null],["Honey",5,12,"2 tsp",null,null],["Salt-reduced soy sauce",10,15,"1 tbsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"bud-c-snack","f":"budget","d":"C","m":"snack","n":"Rice cakes with peanut butter and banana","ds":"Crunchy, sweet and filling. Two minutes to make.","pr":2,"ck":0,"st":["Spread the peanut butter evenly over the two rice cakes.","Slice the banana and lay the slices on top.","Have it with a glass of cold milk."],"tp":"Eat the rice cakes straight away. They go soft if they sit with the banana on top.","dt":[],"c":314,"p":12.8,"cb":38.2,"ft":11.3,"ps":23,"i":[["Plain rice cakes",84,20,"2 rice cakes",null,null],["Peanut butter, no added sugar",23,15,"1 tbsp",null,null],["Banana",24,60,"1/2 banana",null,null],["Reduced fat milk",1,200,"1 glass",null,null]]}]$json$::jsonb)),
ins as (
  insert into public.recipes (id, slug, family, day_type, meal_type, name, description, prep_minutes, cook_minutes, steps, tip, diets, calories, protein_g, carbs_g, fats_g, position)
  select md5('unfnshd-meal-library:' || (r->>'k'))::uuid, r->>'k', r->>'f', r->>'d', r->>'m', r->>'n', r->>'ds', (r->>'pr')::int, (r->>'ck')::int, r->'st', r->>'tp',
    array(select jsonb_array_elements_text(r->'dt')), (r->>'c')::int, (r->>'p')::numeric, (r->>'cb')::numeric, (r->>'ft')::numeric, (r->>'ps')::int
  from d on conflict (id) do nothing
  returning id
)
insert into public.recipe_ingredients (id, recipe_id, position, label, food_id, grams, measure, each_label, each_grams, calories, protein_g, carbs_g, fats_g)
select md5('unfnshd-meal-library:' || ((r->>'k') || ':ing:' || (x.ord - 1)))::uuid, md5('unfnshd-meal-library:' || (r->>'k'))::uuid, x.ord - 1, x.e->>0, fd.id, (x.e->>2)::numeric, x.e->>3, x.e->>4, (x.e->>5)::numeric,
  round(fd.calories * (x.e->>2)::numeric / 100, 1), round(fd.protein_g * (x.e->>2)::numeric / 100, 1), round(fd.carbs_g * (x.e->>2)::numeric / 100, 1), round(fd.fats_g * (x.e->>2)::numeric / 100, 1)
from d cross join lateral jsonb_array_elements(r->'i') with ordinality as x(e, ord)
cross join f
join public.foods fd on fd.id = ((f.ids)->>((x.e->>1)::int))::uuid
on conflict (id) do nothing;
